			rows.add(new Row(64, plane, 1, runRef(ordinal++)));
			rows.add(new Row(64, plane, Long.MAX_VALUE, runRef(ordinal++)));
			rows.add(new Row(64, plane, Long.MIN_VALUE, runRef(ordinal++)));
			rows.add(new Row(64, plane, -1, runRef(ordinal++)));
			rows.add(new Row(Long.MAX_VALUE, plane, predicate, runRef(ordinal++)));
			rows.add(new Row(Long.MIN_VALUE, plane, predicate, runRef(ordinal++)));
			rows.add(new Row(Long.MIN_VALUE + 1, plane, predicate, runRef(ordinal++)));
			rows.add(new Row(-2, plane, predicate, runRef(ordinal++)));
